<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { onBeforeRouteLeave, useRouter } from 'vue-router';
import PortalLayout from '../layouts/PortalLayout.vue';
import PasswordRequirements from '../components/PasswordRequirements.vue';
import FileUpload from '../components/FileUpload.vue';
import { passwordValid } from '../../../shared/password-policy.js';
import api from '../services/api';
import { mailRequestConfig } from '../services/api';
import { useAuthStore } from '../stores/auth';
import { theme, saveTheme, useServerTheme } from '../services/theme';

const auth=useAuthStore(),router=useRouter();
const profile=ref(null),draft=ref(null),editing=ref(false),loading=ref(true),saving=ref(false),error=ref(''),notice=ref('');
const activeTab=ref('overview'),tabs=[['overview','Overview'],['personal','Personal details'],['appearance','Appearance'],['security','Security']];
function onTabKey(event,index){let next=index;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();activeTab.value=tabs[next][0];document.getElementById(`profile-tab-${activeTab.value}`)?.focus();}
function openVerification(){activeTab.value='security';document.getElementById('profile-tab-security')?.focus();}
const password=ref({currentPassword:'',newPassword:'',confirm:''});
const emailForm=ref({newEmail:'',currentPassword:''});
const pendingEmail=ref(null),pendingExpiresAt=ref(null),pendingDelivery=ref(null);
const verification=ref(null),verificationCooldown=ref(0),verificationMessage=ref('');let verificationTimer;
const idForm=ref({externalId:'',currentPassword:'',reason:''});
const mailCheckEmail=ref(''),mailDiagnostics=ref(null),mailChecking=ref(false);
const sessions=ref([]),sessionTotal=ref(0),sessionPage=ref(1),sessionsLoading=ref(false),sessionsDialog=ref(null),allSessions=ref([]);
const photoUrl=ref(''),previewUrl=ref(''),selectedPhoto=ref(null),removePhoto=ref(false),photoInput=ref(null);
const photoProgress=ref(null);
const fullName=computed(()=>[profile.value?.firstName,profile.value?.middleName,profile.value?.lastName].filter(Boolean).join(' '));
function editable(p){return p?{firstName:p.firstName||'',middleName:p.middleName||'',lastName:p.lastName||'',position:p.position||'',phone:p.phone||'',receiveOptionalNotifications:Boolean(p.receiveOptionalNotifications)}:null;}
const dirty=computed(()=>editing.value&&(JSON.stringify(draft.value)!==JSON.stringify(editable(profile.value))||selectedPhoto.value||removePhoto.value));
function clearPreview(){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';selectedPhoto.value=null;removePhoto.value=false;if(photoInput.value)photoInput.value.value='';}
function clearPhoto(){if(photoUrl.value)URL.revokeObjectURL(photoUrl.value);photoUrl.value='';}
async function refreshPhoto(){clearPhoto();if(!profile.value?.photoVersion)return;try{const response=await api.get('/account/photo',{responseType:'blob'});photoUrl.value=URL.createObjectURL(response.data);}catch{error.value='Profile loaded, but the photo could not be displayed.';}}
async function load(){loading.value=true;try{profile.value=(await api.get('/account/profile')).data.data;useServerTheme(profile.value.themePreference||'system');draft.value=editable(profile.value);idForm.value.externalId=profile.value.externalId||'';await Promise.all([refreshPhoto(),loadPendingEmail(),loadSessions(),loadVerification()]);}catch(e){error.value=e.response?.data?.message||'Could not load profile.';}finally{loading.value=false;}}
function updateVerificationCountdown(){const until=verification.value?.nextAllowedAt;verificationCooldown.value=until?Math.max(0,Math.ceil((new Date(until).getTime()-Date.now())/1000)):0;}
async function loadVerification(){verification.value=(await api.get('/account/email-verification')).data.data;updateVerificationCountdown();if(verification.value?.verifiedAt&&profile.value)profile.value.emailVerifiedAt=verification.value.verifiedAt;}
async function requestVerification(){if(saving.value||verificationCooldown.value||profile.value?.emailVerifiedAt)return;saving.value=true;error.value='';notice.value='';verificationMessage.value='';try{const result=await api.post('/account/email-verification',{},mailRequestConfig);verificationMessage.value=result.data.message;await loadVerification();}catch(e){const response=e.response?.data;if(response?.nextAllowedAt){verification.value={...verification.value,nextAllowedAt:response.nextAllowedAt};updateVerificationCountdown();}if(e.response?.status===429)verificationMessage.value=response?.message||'Please wait before resending.';else error.value=response?.message||'Could not send verification email.';await loadVerification().catch(()=>{});}finally{saving.value=false;}}
async function loadSessions(){sessionsLoading.value=true;try{const result=(await api.get('/account/sessions')).data.data;sessions.value=result.rows;sessionTotal.value=result.total;if(sessionsDialog.value?.open)await loadAllSessions();}finally{sessionsLoading.value=false;}}
async function loadAllSessions(){const result=(await api.get('/account/sessions',{params:{all:true,page:sessionPage.value}})).data.data;allSessions.value=result.rows;sessionTotal.value=result.total;}
async function openSessions(){sessionPage.value=1;allSessions.value=[];sessionsDialog.value.showModal();await loadAllSessions();}
async function sessionPageTo(page){sessionPage.value=page;await loadAllSessions();}
async function loadPendingEmail(){const response=(await api.get('/account/email-change/pending')).data.data;pendingEmail.value=response.pending?.pendingEmail||null;pendingExpiresAt.value=response.pending?.expiresAt||null;pendingDelivery.value=response.delivery?.outcome||null;}
async function changeTheme(value){error.value='';try{await saveTheme(value);profile.value.themePreference=value;notice.value='Appearance preference saved.';}catch(e){error.value=e.response?.data?.message||'Could not save appearance preference.';}}
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue='';}}
function onVisibility(){if(document.visibilityState==='visible')loadVerification().catch(()=>{});}
onMounted(()=>{verificationTimer=setInterval(updateVerificationCountdown,1000);document.addEventListener('visibilitychange',onVisibility);load();});window.addEventListener('beforeunload',beforeUnload);
onBeforeUnmount(()=>{clearPhoto();clearPreview();clearInterval(verificationTimer);document.removeEventListener('visibilitychange',onVisibility);window.removeEventListener('beforeunload',beforeUnload);});
onBeforeRouteLeave(()=>!dirty.value||window.confirm('Discard your unsaved profile changes?'));
function edit(){error.value='';notice.value='';draft.value=editable(profile.value);editing.value=true;}
function cancel(){clearPreview();draft.value=editable(profile.value);editing.value=false;error.value='';}
function choosePhoto(event){const file=event.target.files?.[0];if(!file)return;if(file.size>10*1024*1024){error.value='Choose a photo no larger than 10 MB.';event.target.value='';return;}clearPreview();selectedPhoto.value=file;previewUrl.value=URL.createObjectURL(file);}
function selectPhoto(file){choosePhoto({target:{files:[file],value:''}});}
async function save(){if(saving.value||!editing.value)return;saving.value=true;error.value='';notice.value='';try{
  const payload=profile.value.role==='ADMIN'?draft.value:{phone:draft.value.phone,receiveOptionalNotifications:draft.value.receiveOptionalNotifications};
  await api.patch('/account/profile',payload);
  if(selectedPhoto.value){const data=new FormData();data.append('photo',selectedPhoto.value);photoProgress.value=0;await api.put('/account/photo',data,{onUploadProgress:event=>{if(event.total)photoProgress.value=Math.round(event.loaded*100/event.total);}});}
  else if(removePhoto.value)await api.delete('/account/photo');
  clearPreview();editing.value=false;await load();
  auth.user={...auth.user,firstName:profile.value.firstName,middleName:profile.value.middleName,lastName:profile.value.lastName};
  window.dispatchEvent(new Event('sbaa:profile'));notice.value='Profile changes saved.';
}catch(e){error.value=e.response?.data?.message||'Could not save all profile changes. Review your details and try again.';}finally{saving.value=false;photoProgress.value=null;}}
async function changePassword(){if(saving.value)return;error.value='';notice.value='';if(!passwordValid(password.value.newPassword)||password.value.newPassword!==password.value.confirm){error.value='Complete the password checklist before continuing.';return;}saving.value=true;try{await api.post('/account/change-password',password.value);auth.clearLocal();router.push('/login');}catch(e){error.value=e.response?.data?.message||'Could not change password.';}finally{saving.value=false;}}
async function logoutOthers(){if(saving.value)return;saving.value=true;error.value='';try{await api.post('/account/logout-others');await loadSessions();notice.value='Other sessions signed out.';}catch(e){error.value=e.response?.data?.message||'Could not sign out other sessions.';}finally{saving.value=false;}}
async function revokeSession(session){if(saving.value)return;saving.value=true;error.value='';try{const result=await api.patch(`/account/sessions/${session.id}/revoke`);if(result.data.data.current){auth.clearLocal();router.push('/login');return;}await loadSessions();notice.value='Selected session revoked.';}catch(e){error.value=e.response?.data?.message||'Could not revoke this session.';}finally{saving.value=false;}}
async function requestEmailChange(){if(saving.value)return;saving.value=true;error.value='';notice.value='';try{notice.value=(await api.post('/account/email-change',emailForm.value,mailRequestConfig)).data.message;emailForm.value={newEmail:'',currentPassword:''};await loadPendingEmail();}catch(e){error.value=e.response?.data?.message||'Could not request email verification.';}finally{saving.value=false;}}
async function resendEmailChange(){if(!pendingEmail.value||saving.value)return;emailForm.value.newEmail=pendingEmail.value;await requestEmailChange();}
async function cancelEmailChange(){if(saving.value)return;saving.value=true;error.value='';try{await api.delete('/account/email-change/pending');await loadPendingEmail();notice.value='Pending email change cancelled.';}catch(e){error.value=e.response?.data?.message||'Could not cancel the email change.';}finally{saving.value=false;}}
async function changeAccountId(){if(saving.value)return;saving.value=true;error.value='';notice.value='';try{const response=await api.patch('/account/account-id',idForm.value);profile.value.externalId=response.data.data.externalId;idForm.value={externalId:profile.value.externalId,currentPassword:'',reason:''};notice.value='Account ID updated.';}catch(e){error.value=e.response?.data?.message||'Could not change Account ID.';}finally{saving.value=false;}}
async function checkMail(){mailChecking.value=true;error.value='';try{mailDiagnostics.value=(await api.get('/admin/mail-diagnostics',{params:{email:mailCheckEmail.value||undefined}})).data.data;}catch(e){error.value=e.response?.data?.message||'Could not load mail diagnostics.';}finally{mailChecking.value=false;}}
</script>
<template>
  <PortalLayout title="Profile"><div class="dashboard content-page profile-page">
    <div class="page-heading"><div><p class="eyebrow">YOUR ACCOUNT</p><h2>Profile & security</h2><p>Your personal contact details are separate from department contact information.</p></div></div>
    <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message profile-confirmation" role="status">{{notice}}</p>
    <p v-if="loading" class="empty">Loading profile…</p>
    <template v-else-if="profile">
      <section class="profile-identity"><span class="profile-avatar"><img v-if="previewUrl||(!removePhoto&&photoUrl)" :src="previewUrl||photoUrl" alt="Your profile photo"/><span v-else>{{profile.firstName?.[0]}}{{profile.lastName?.[0]}}</span></span><div><h2>{{fullName}}</h2><span class="role-badge">{{profile.role}}</span><p v-if="profile.position">{{profile.position}}</p><p>{{profile.email}} <span class="status-badge">{{profile.emailVerifiedAt?'Verified email':'Email not verified'}}</span></p></div><div class="inline-actions"><button v-if="!profile.emailVerifiedAt" type="button" class="primary" @click="openVerification">Verify my email</button><button v-if="!editing" class="secondary-button profile-edit-button" @click="edit();activeTab='personal'">Edit profile</button></div></section>
      <div class="profile-tabs" role="tablist" aria-label="Profile sections"><button v-for="([key,label],index) in tabs" :id="`profile-tab-${key}`" :key="key" type="button" role="tab" :aria-selected="activeTab===key" :aria-controls="`profile-panel-${key}`" :tabindex="activeTab===key?0:-1" @click="activeTab=key" @keydown="onTabKey($event,index)">{{label}}</button></div>
      <section v-show="activeTab==='overview'" id="profile-panel-overview" class="profile-overview" role="tabpanel" aria-labelledby="profile-tab-overview"><article class="panel"><h2>Account overview</h2><dl class="detail-list"><div><dt>Name</dt><dd>{{fullName}}</dd></div><div><dt>Role</dt><dd>{{profile.role}}</dd></div><div><dt>Email</dt><dd>{{profile.email}}</dd></div><div><dt>Personal phone</dt><dd>{{profile.phone||'Not provided'}}</dd></div><div><dt>Account ID</dt><dd>{{profile.externalId||'—'}}</dd></div></dl></article></section>
      <div class="profile-sections"><div v-show="activeTab==='personal'" id="profile-panel-personal" class="profile-column" role="tabpanel" aria-labelledby="profile-tab-personal"><section class="panel"><div class="panel-title"><h2>Personal details</h2><span v-if="profile.role!=='ADMIN'">Institutional identity is administrator-managed</span></div>
        <form v-if="editing" class="stack-form" @submit.prevent="save"><div v-if="profile.role==='ADMIN'" class="profile-name-grid"><label>First name<input v-model="draft.firstName" autocomplete="given-name" required maxlength="100"/></label><label>Middle name (optional)<input v-model="draft.middleName" autocomplete="additional-name" maxlength="100"/></label><label>Last name<input v-model="draft.lastName" autocomplete="family-name" required maxlength="100"/></label><label>Position/title<input v-model="draft.position" maxlength="100"/></label></div><label>Personal phone<input v-model="draft.phone" autocomplete="tel" maxlength="30"/></label><label class="check-label"><input v-model="draft.receiveOptionalNotifications" type="checkbox"/><span>Receive optional notifications</span></label><p class="field-help">Academic and security messages are always sent.</p><div class="photo-editor"><strong>Profile photo</strong><FileUpload :file="selectedPhoto" :preview="previewUrl" :max-mb="10" :busy="saving&&!!selectedPhoto" :progress="photoProgress" label="Select or drop profile photo" hint="PNG, JPEG, or WebP, up to 10 MB. The server checks and resizes the image." @select="selectPhoto" @remove="clearPreview"/><button v-if="photoUrl||previewUrl" type="button" class="text-button" @click="clearPreview();removePhoto=true">Remove current photo</button></div><div class="profile-actions"><button class="primary" :disabled="saving">{{saving?'Saving…':'Save changes'}}</button><button type="button" class="secondary-button" :disabled="saving" @click="cancel">Cancel</button></div></form>
        <dl v-else class="detail-list"><div><dt>Name</dt><dd>{{fullName}}</dd></div><div><dt>Role</dt><dd>{{profile.role}}</dd></div><div v-if="profile.position"><dt>Position</dt><dd>{{profile.position}}</dd></div></dl>
      </section>
      <section class="panel"><h2>Contact details</h2><dl class="detail-list"><div><dt>Personal phone</dt><dd>{{profile.phone||'Not provided'}}</dd></div><div><dt>Optional notices</dt><dd>{{profile.receiveOptionalNotifications?'On':'Off'}}</dd></div></dl></section><section class="panel"><h2>Institutional information</h2><dl class="detail-list"><div><dt>Account ID</dt><dd>{{profile.externalId||'—'}}</dd></div><div v-if="profile.program"><dt>Program</dt><dd>{{profile.program}}</dd></div><div v-if="profile.section"><dt>Section</dt><dd>{{profile.section}}</dd></div><div v-if="profile.yearLevel"><dt>Year level</dt><dd>{{profile.yearLevel}}</dd></div></dl></section></div><div v-show="activeTab==='appearance'" id="profile-panel-appearance" class="profile-column" role="tabpanel" aria-labelledby="profile-tab-appearance"><section class="panel"><h2>Appearance & preferences</h2><p class="subtle">System follows your device setting. Your choice is saved to this account.</p><div class="theme-options" role="group" aria-label="Appearance"><button v-for="choice in ['light','dark','system']" :key="choice" type="button" class="secondary-button" :class="{selected:theme===choice}" :aria-pressed="theme===choice" @click="changeTheme(choice)">{{choice[0].toUpperCase()+choice.slice(1)}}</button></div></section></div><div v-show="activeTab==='security'" id="profile-panel-security" class="profile-column" role="tabpanel" aria-labelledby="profile-tab-security"><div class="profile-settings"><section class="panel"><h2>Email & account</h2><p class="subtle">Your login email is used to access the portal and receive account messages. Your current email remains active until the new address is verified.</p><p v-if="pendingEmail" class="field-help">Pending: <strong>{{pendingEmail}}</strong> · {{pendingDelivery==='PROVIDER_ACCEPTED'?'Accepted by the mail provider; inbox receipt is not confirmed.':'Verification requested.'}} Expires {{new Date(pendingExpiresAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}} (Asia/Manila).</p><form class="stack-form" @submit.prevent="requestEmailChange"><label>New email<input v-model="emailForm.newEmail" type="email" autocomplete="email" required maxlength="190"/></label><label>Current portal password<input v-model="emailForm.currentPassword" type="password" autocomplete="current-password" required/></label><div class="inline-actions"><button class="primary" :disabled="saving">{{saving?'Sending…':'Send verification'}}</button><button v-if="pendingEmail" type="button" class="secondary-button" :disabled="saving||!emailForm.currentPassword" @click="resendEmailChange">Resend to pending address</button><button v-if="pendingEmail" type="button" class="text-button" :disabled="saving" @click="cancelEmailChange">Cancel request</button></div></form></section>
      <section v-if="profile.role==='ADMIN'" class="panel"><h2>Administrator Account ID</h2><p class="subtle">This changes only the visible Account ID, not the database record ID. The change is audited.</p><form class="stack-form" @submit.prevent="changeAccountId"><label>Account ID<input v-model="idForm.externalId" required minlength="4" maxlength="40" pattern="[A-Za-z0-9-]+"/></label><label>Current portal password<input v-model="idForm.currentPassword" type="password" autocomplete="current-password" required/></label><label>Reason for change<input v-model="idForm.reason" required maxlength="500"/></label><button class="primary" :disabled="saving">Update Account ID</button></form></section></div>
      <section v-if="profile.role==='ADMIN'" class="panel"><h2>Mail diagnostics</h2><p class="subtle">Check portal configuration and provider outcomes. Mailbox receipt requires checking the provider and recipient inbox separately.</p><form class="toolbar" @submit.prevent="checkMail"><label>Account email (optional)<input v-model="mailCheckEmail" type="email" placeholder="Filter by account"/></label><button class="secondary-button" :disabled="mailChecking">{{mailChecking?'Checking…':'Check mail status'}}</button></form><div v-if="mailDiagnostics" class="mail-diagnostics"><p><strong>Mode:</strong> {{mailDiagnostics.mode}} <template v-if="mailDiagnostics.mode==='resend'">· <strong>HTTPS provider:</strong> {{mailDiagnostics.httpsProviderConfigured?'configured':'missing'}}</template><template v-else>· <strong>SMTP host:</strong> {{mailDiagnostics.smtpHostConfigured?'set':'missing'}} · <strong>Sender:</strong> {{mailDiagnostics.smtpSenderConfigured?'set':'missing'}} · <strong>Credentials:</strong> {{mailDiagnostics.smtpCredentialsConfigured?'set':'missing'}}</template></p><p><strong>Frontend link origin:</strong> {{mailDiagnostics.publicUrl}}</p><p v-if="mailCheckEmail"><strong>Account status:</strong> {{mailDiagnostics.account?.status||'No matching account'}}</p><p v-if="mailDiagnostics.mode==='development'" class="form-error">Development mode writes links to a private server log; it does not send email.</p><div v-for="event in mailDiagnostics.events" :key="event.id" class="record-row"><span>{{event.purpose}} · {{event.outcome}} · {{new Date(event.createdAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}} (Asia/Manila)</span><small v-if="event.messageId">Provider message ID: {{event.messageId}}</small><small v-if="event.errorCode">Code: {{event.errorCode}}</small></div><p v-if="!mailDiagnostics.events.length" class="empty">No matching mail outcomes recorded yet.</p></div></section>
      <section class="panel narrow-panel profile-security"><h2>Active sessions ({{sessionTotal}})</h2><p v-if="profile.lastLoginAt" class="subtle">Last sign-in: {{new Date(profile.lastLoginAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}} (Asia/Manila)</p><p v-if="sessionsLoading" class="empty">Loading sessions…</p><div v-for="session in sessions" :key="session.id" class="session-row"><div><strong>{{session.current?'This session':session.device||'Other session'}}</strong><small>Started {{new Date(session.createdAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}} · Last active {{new Date(session.lastSeenAt||session.createdAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}} (Asia/Manila)</small></div><button type="button" class="text-button destructive" :disabled="saving" @click="revokeSession(session)">Sign out</button></div><div class="inline-actions"><button type="button" class="secondary-button" @click="openSessions">Manage all sessions ({{sessionTotal}})</button><button type="button" class="secondary-button" :disabled="saving||sessionTotal<2" @click="logoutOthers">Sign out of other sessions</button></div></section>
      <dialog ref="sessionsDialog" class="sessions-dialog" aria-labelledby="sessions-dialog-title"><div class="panel-title"><h2 id="sessions-dialog-title">Manage active sessions</h2><button type="button" class="text-button" @click="sessionsDialog.close()">Close</button></div><p>Only sessions that have not expired or been signed out are shown.</p><div v-for="session in allSessions" :key="session.id" class="session-row"><div><strong>{{session.current?'This session':session.device||'Other session'}}</strong><small>Started {{new Date(session.createdAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}} · Last active {{new Date(session.lastSeenAt||session.createdAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}} (Asia/Manila)</small></div><button type="button" class="text-button destructive" :disabled="saving" @click="revokeSession(session)">Sign out</button></div><div class="pagination"><button :disabled="sessionPage===1" @click="sessionPageTo(sessionPage-1)">Previous</button><span>Page {{sessionPage}} · {{sessionTotal}} sessions</span><button :disabled="sessionPage*10>=sessionTotal" @click="sessionPageTo(sessionPage+1)">Next</button></div></dialog>
      <section class="panel narrow-panel profile-security"><h2>Change password</h2><form class="stack-form" @submit.prevent="changePassword"><label>Current password<input v-model="password.currentPassword" type="password" autocomplete="current-password" required/></label><PasswordRequirements v-model="password.newPassword" v-model:confirm="password.confirm" id-prefix="change" confirm-label="Confirm new password"/><p class="field-help">Changing your password signs out every session.</p><button class="primary" :disabled="saving">{{saving?'Updating…':'Change password'}}</button></form></section></div>
      <section v-show="activeTab==='security'" v-if="!profile.emailVerifiedAt" class="panel narrow-panel profile-security"><h2>Verify your current email</h2><p>Send a secure link to <strong>{{profile.email}}</strong>. Opening it verifies mailbox ownership, not school-record identity.</p><p v-if="verificationMessage" class="field-help" role="status">{{verificationMessage}}</p><p v-if="verification?.deliveryOutcome==='PROVIDER_ACCEPTED'" class="field-help">Accepted by the provider; inbox receipt is not confirmed.</p><p v-if="verification?.deliveryOutcome==='PROVIDER_UNKNOWN'" class="field-help">Provider outcome is uncertain. Check your inbox before requesting another link.</p><p v-if="verification?.deliveryOutcome==='PROVIDER_REJECTED'" class="field-help">The previous attempt was rejected before delivery.</p><p v-if="verification?.deliveryOutcome==='DEVELOPMENT_LOG'" class="field-help">Development mode logged a link; no email was sent.</p><button type="button" class="primary" :disabled="saving||verificationCooldown>0" @click="requestVerification">{{saving?'Sending…':verificationCooldown?`Resend in ${verificationCooldown}s`:verification?.lastRequestedAt?'Resend verification':'Verify my email'}}</button></section>
      </div>
    </template>
  </div></PortalLayout>
</template>
<style scoped>.sessions-dialog{width:min(42rem,calc(100vw - 2rem));max-height:min(80vh,48rem);overflow:auto;border:1px solid var(--line);border-radius:1rem;background:var(--surface);color:var(--text);padding:1.5rem;box-shadow:0 1rem 3rem #0004}.sessions-dialog::backdrop{background:#061b14a8}@media(max-width:600px){.sessions-dialog{width:100vw;max-width:100vw;height:100dvh;max-height:100dvh;margin:0;border-radius:0}}</style>
